    Bug 1816238 - Use readyState to wait for content loads in tests. r=mkmelin

    While investigating timeouts of `browser_browserContext.js`, it was
    observed that the condition to wait for a load event was triggered by
    `browser.webProgress.isLoadingDocument` being `true`, but the load event
    was never seen.

    The `readyState` however was already `complete`. This patch therefore
    changes the wait-for-load condition of content loads, here and in
    similar tests.

    Differential Revision: https://phabricator.services.mozilla.com/D228429

diff --git a/mail/base/test/browser/browser_browserContext.js b/mail/base/test/browser/browser_browserContext.js
index 65fe6545e97..ad696e8d2c8 100644
--- a/mail/base/test/browser/browser_browserContext.js
+++ b/mail/base/test/browser/browser_browserContext.js
@@ -56,13 +56,13 @@ function checkMenuitems(menu, ...expectedItems) {

 async function checkABrowser(browser, doc = browser.ownerDocument) {
   if (
-    browser.webProgress?.isLoadingDocument ||
+    browser.ownerDocument.readyState != "complete" ||
     !browser.currentURI ||
     browser.currentURI?.spec == "about:blank"
   ) {
     await BrowserTestUtils.browserLoaded(
       browser,
-      undefined,
+      false,
       url => url != "about:blank"
     );
   }
